<script setup lang="ts">
import { ref } from 'vue'
import { useLang } from '~/composables/useLang'

const props = defineProps<{
  title: string
  url: string
  summary?: string
}>()

const { t } = useLang()
const showMenu = ref(false)

const shareTo = (platform: string) => {
  let shareUrl = ''
  if (platform === 'twitter') {
    shareUrl = `https://twitter.com/intent/tweet?text=${encodeURIComponent(props.title + ' - ' + (props.summary || ''))}&url=${encodeURIComponent(props.url)}`
  } else if (platform === 'weibo') {
    shareUrl = `https://service.weibo.com/share/share.php?title=${encodeURIComponent(props.title)}&url=${encodeURIComponent(props.url)}&content=${encodeURIComponent(props.summary || '')}`
  } else if (platform === 'facebook') {
    shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(props.url)}&quote=${encodeURIComponent(props.summary || '')}`
  } else if (platform === 'linkedin') {
    shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(props.url)}`
  } else if (platform === 'telegram') {
    shareUrl = `https://t.me/share/url?url=${encodeURIComponent(props.url)}&text=${encodeURIComponent(props.title + ' - ' + (props.summary || ''))}`
  } else if (platform === 'qqspace') {
    shareUrl = `https://sns.qzone.qq.com/cgi-bin/qzshare/cgi_qzshare_url?url=${encodeURIComponent(props.url)}`
  }
  window.open(shareUrl, '_blank', 'width=600,height=400')
}

const copyLink = async () => {
  try {
    const text = `${props.title}\n${props.summary || ''}\n${props.url}`
    await navigator.clipboard.writeText(text)
    alert(t('share.copied'))
  } catch {
    alert(t('share.copyFailed'))
  }
}
</script>
